function [r, v] = verlet(r0, v0, h, mu)
%VERLET  One velocity-Verlet step of h over the two-body + J2 acceleration: r + (v h + a0 h h/2), then v + (a0 + a1) h/2 with
%   a1 at the new r, element by element as the tick wrote them.
%   r0: real[1][3] (passed a plain number)
%   v0: real[1][3] (passed a plain number)
%   h: real[1] (passed a plain number)
